// Chantier environnements-de-pr, lot A: the deployment of the web service, as Infrastructure as Code. Railway stops
// reading railway.json on 2026-12-01. Generated by `railway config migrate` for each environment, then joined:
// only the branch and the domains differ. Railway does not read this file at deploy time; it is applied per environment
// with `railway config plan` then `railway config apply`, once `railway config migrate cutover` has switched the
// service off railway.json. PR environments copy Develop's settings, they are never applied from here.
// Partial: only the web service is managed here; Postgres, the buckets and the variables stay as they are in Railway.
import { defineRailway, github, project, service } from "railway/iac";

export const partial = "App.Lnclassapp";

const ENVIRONMENTS: Record<string, { branch: string; domains: string[] }> = {
  production: { branch: "main", domains: ["lnclass.com", "www.lnclass.com"] },
  Staging: { branch: "Staging", domains: ["app-staging.lnclass.com", "staging.lnclass.com"] },
  Develop: { branch: "Develop", domains: ["app-develop.lnclass.com", "develop.lnclass.com"] },
};

export default defineRailway((ctx) => {
  const environment = ENVIRONMENTS[ctx.environment];
  if (!environment) throw new Error(`.railway/railway.ts: unknown environment ${ctx.environment}`);

  const app = service("App.Lnclassapp", {
    source: github("Lnclassapp/App.Lnclassapp", { branch: environment.branch, checkSuites: false }),
    build: { buildEnvironment: "V3", builder: "DOCKERFILE", dockerfilePath: "Dockerfile" },
    healthcheck: "/up",
    healthcheckTimeout: 120,
    // ADR-0052, ADR-0034: migrations, then the seeds of the environment, before each deploy.
    preDeploy: "bin/rails db:prepare db:seed",
    replicas: { "europe-west4-drams3a": 1 },
    deploy: { sleepApplication: true },
    domains: environment.domains,
    networking: { privateNetworkEndpoint: "applnclassapp" },
    cdn: { enabled: true },
  });

  return project("App.Lnclassapp", {
    variables: { managed: false },
    resources: [app],
  });
});
